import java.io.InputStream;
import java.io.IOException;

public class Main {

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public int nextInt() {
            int c = readByte();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = readByte();
            }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = readByte();
            }
            return res;
        }
    }

    static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    static class Node {
        long ans;
        int prefSz;
        int[] prefG = new int[32];
        int[] prefCnt = new int[32];

        int suffSz;
        int[] suffG = new int[32];
        int[] suffCnt = new int[32];

        void setLeaf(int val) {
            if (val > 1) {
                ans = 1;
                prefSz = 1;
                prefG[0] = val;
                prefCnt[0] = 1;

                suffSz = 1;
                suffG[0] = val;
                suffCnt[0] = 1;
            } else {
                ans = 0;
                prefSz = 0;
                suffSz = 0;
            }
        }
    }

    static Node[] tree;
    static int[] S;

    static void combine(Node res, Node left, Node right) {
        long cross = 0;
        for (int i = 0; i < left.suffSz; i++) {
            int gA = left.suffG[i];
            long cA = left.suffCnt[i];
            for (int j = 0; j < right.prefSz; j++) {
                if (gcd(gA, right.prefG[j]) > 1) {
                    cross += cA * right.prefCnt[j];
                }
            }
        }
        res.ans = left.ans + right.ans + cross;

        // Merge prefixes
        int pSz = 0;
        for (int i = 0; i < left.prefSz; i++) {
            res.prefG[pSz] = left.prefG[i];
            res.prefCnt[pSz] = left.prefCnt[i];
            pSz++;
        }
        for (int j = 0; j < right.prefSz; j++) {
            int g = left.prefSz > 0 ? gcd(res.prefG[pSz - 1], right.prefG[j]) : right.prefG[j];
            if (g == 1) break;
            if (pSz > 0 && res.prefG[pSz - 1] == g) {
                res.prefCnt[pSz - 1] += right.prefCnt[j];
            } else {
                res.prefG[pSz] = g;
                res.prefCnt[pSz] = right.prefCnt[j];
                pSz++;
            }
        }
        res.prefSz = pSz;

        // Merge suffixes
        int sSz = 0;
        for (int i = 0; i < right.suffSz; i++) {
            res.suffG[sSz] = right.suffG[i];
            res.suffCnt[sSz] = right.suffCnt[i];
            sSz++;
        }
        for (int j = 0; j < left.suffSz; j++) {
            int g = right.suffSz > 0 ? gcd(res.suffG[sSz - 1], left.suffG[j]) : left.suffG[j];
            if (g == 1) break;
            if (sSz > 0 && res.suffG[sSz - 1] == g) {
                res.suffCnt[sSz - 1] += left.suffCnt[j];
            } else {
                res.suffG[sSz] = g;
                res.suffCnt[sSz] = left.suffCnt[j];
                sSz++;
            }
        }
        res.suffSz = sSz;
    }

    static void build(int node, int l, int r) {
        if (l == r) {
            tree[node].setLeaf(S[l]);
            return;
        }
        int mid = (l + r) >>> 1;
        build(node << 1, l, mid);
        build((node << 1) | 1, mid + 1, r);
        combine(tree[node], tree[node << 1], tree[(node << 1) | 1]);
    }

    static void update(int node, int l, int r, int idx, int val) {
        if (l == r) {
            S[l] = val;
            tree[node].setLeaf(val);
            return;
        }
        int mid = (l + r) >>> 1;
        if (idx <= mid) {
            update(node << 1, l, mid, idx, val);
        } else {
            update((node << 1) | 1, mid + 1, r, idx, val);
        }
        combine(tree[node], tree[node << 1], tree[(node << 1) | 1]);
    }

    static Node temp = new Node();

    static void query(int node, int l, int r, int ql, int qr, Node res) {
        if (ql <= l && r <= qr) {
            if (res.prefSz == -1) {
                // Copy directly
                res.ans = tree[node].ans;
                res.prefSz = tree[node].prefSz;
                System.arraycopy(tree[node].prefG, 0, res.prefG, 0, tree[node].prefSz);
                System.arraycopy(tree[node].prefCnt, 0, res.prefCnt, 0, tree[node].prefSz);
                res.suffSz = tree[node].suffSz;
                System.arraycopy(tree[node].suffG, 0, res.suffG, 0, tree[node].suffSz);
                System.arraycopy(tree[node].suffCnt, 0, res.suffCnt, 0, tree[node].suffSz);
            } else {
                combine(temp, res, tree[node]);
                // Copy back to res
                res.ans = temp.ans;
                res.prefSz = temp.prefSz;
                System.arraycopy(temp.prefG, 0, res.prefG, 0, temp.prefSz);
                System.arraycopy(temp.prefCnt, 0, res.prefCnt, 0, temp.prefSz);
                res.suffSz = temp.suffSz;
                System.arraycopy(temp.suffG, 0, res.suffG, 0, temp.suffSz);
                System.arraycopy(temp.suffCnt, 0, res.suffCnt, 0, temp.suffSz);
            }
            return;
        }
        int mid = (l + r) >>> 1;
        if (ql <= mid) {
            query(node << 1, l, mid, ql, qr, res);
        }
        if (qr > mid) {
            query((node << 1) | 1, mid + 1, r, ql, qr, res);
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        if (n == -1) return;
        int m = scanner.nextInt();

        S = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            S[i] = scanner.nextInt();
        }

        tree = new Node[4 * n + 1];
        for (int i = 0; i < tree.length; i++) {
            tree[i] = new Node();
        }

        build(1, 1, n);

        StringBuilder sb = new StringBuilder();
        Node qRes = new Node();

        for (int q = 0; q < m; q++) {
            int type = scanner.nextInt();
            if (type == 1) {
                int idx = scanner.nextInt();
                int val = scanner.nextInt();
                update(1, 1, n, idx, val);
            } else {
                int l = scanner.nextInt();
                int r = scanner.nextInt();
                qRes.prefSz = -1; // Flag indicating uninitialized
                query(1, 1, n, l, r, qRes);
                sb.append(qRes.ans).append('\n');
            }
        }

        System.out.print(sb);
    }
}
